script.setup:
// ngraph.graph holds a generated graph (communities that grow like trees, linked into a
// larger tree); ngraph.forcelayout lays it out in 3D, a couple of steps per frame.
const createGraph = (m => m.default ?? m)(await ctx.utils.import("https://cdn.jsdelivr.net/npm/ngraph.graph@20.1.2/+esm"));
const createLayout = (m => m.default ?? m)(await ctx.utils.import("https://cdn.jsdelivr.net/npm/ngraph.forcelayout@3.3.1/+esm"));
// jsDelivr's build, because esm.sh hands ngraph.forcelayout the ngraph.events namespace instead of its function.
const gl = ctx.gl;
const buffer = () => {
  const vao = gl.createVertexArray(), b = gl.createBuffer();
  gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, b);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 20, 0);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 2, gl.FLOAT, false, 20, 12);
  gl.bindVertexArray(null);
  return { vao, b };
};
const program = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec2 a_info;
uniform mat4 u_mvp; uniform float u_px; uniform float u_mode; uniform vec3 u_palette[6];
out vec3 v_color; out float v_fog;
void main(){
  gl_Position = u_mvp * vec4(a_position, 1.0);
  v_fog = clamp(2.1 - gl_Position.w * 0.38, 0.3, 1.0);
  v_color = u_palette[int(mod(a_info.x, 6.0))];
  gl_PointSize = u_mode > 0.5 ? a_info.y * u_px / gl_Position.w : 1.0;
}`, `#version 300 es
precision highp float; in vec3 v_color; in float v_fog; uniform float u_mode; uniform float u_edge; out vec4 outColor;
void main(){
  if (u_mode < 0.5) { outColor = vec4(v_color * u_edge * v_fog, 1.0); return; }
  float d = length(gl_PointCoord - 0.5); if (d > 0.5) discard;
  outColor = vec4(v_color * v_fog * (smoothstep(0.5, 0.15, d) * 1.2 + 0.15), 1.0);
}`);
Object.assign(ctx.state, { createGraph, createLayout, program, edges: buffer(), nodes: buffer(), yaw: 0.4, pitch: 0.25, scale: 1, built: null, moved: false });
ctx.state.build = (communities) => {
  const s = ctx.state, g = createGraph(), size = 140;
  // Each community grows like a tree (every node links to one or two earlier ones);
  // communities hang off each other through a single link.
  for (let c = 0; c < communities; c++) {
    for (let i = 0; i < size; i++) {
      const id = c * size + i;
      g.addNode(id, c);
      if (i > 0) {
        g.addLink(id, c * size + Math.floor(Math.random() ** 1.5 * i));
        if (Math.random() < 0.18) g.addLink(id, c * size + Math.floor(Math.random() * i));
      }
    }
    if (c > 0) for (let k = 0; k < 3; k++) g.addLink(c * size + Math.floor(Math.random() * size), Math.floor(Math.random() * c) * size + Math.floor(Math.random() * size));
  }
  s.layout?.dispose();
  s.graph = g;
  s.layout = createLayout(g, { dimensions: 3, springLength: 12, gravity: -10, dragCoefficient: 0.9, timeStep: 0.5 });
  s.ids = []; g.forEachNode((n) => { s.ids.push(n.id); });
  s.group = s.ids.map((id) => g.getNode(id).data);
  s.degree = s.ids.map((id) => (g.getLinks(id)?.size ?? g.getLinks(id)?.length ?? 1));
  s.index = new Map(s.ids.map((id, i) => [id, i]));
  s.links = []; g.forEachLink((l) => { s.links.push([s.index.get(l.fromId), s.index.get(l.toId)]); });
  s.bodies = s.ids.map((id) => s.layout.getBody(id));
  s.nodeData = new Float32Array(s.ids.length * 5);
  s.edgeData = new Float32Array(s.links.length * 10);
  s.built = communities;
  s.steps = 0;
};

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, M = ctx.utils.mat4;
if (s.built !== u.u_communities || u.u_regenerate) s.build(u.u_communities);
s.layout.simulator.springLength(u.u_spring);
s.layout.simulator.gravity(-u.u_repulsion);
for (let k = 0; k < u.u_steps; k++) s.layout.step();
s.steps += u.u_steps;
// Center on the bounding box and zoom to fit it, smoothly.
const r = s.layout.getGraphRect();
const cx = (r.min_x + r.max_x) / 2, cy = (r.min_y + r.max_y) / 2, cz = (r.min_z + r.max_z) / 2;
const extent = Math.max(r.max_x - r.min_x, r.max_y - r.min_y, r.max_z - r.min_z, 1);
s.scale += (2.3 / extent - s.scale) * 0.08;
s.bodies.forEach((b, i) => s.nodeData.set([(b.pos.x - cx) * s.scale, (b.pos.y - cy) * s.scale, (b.pos.z - cz) * s.scale, s.group[i], 3 + Math.sqrt(s.degree[i]) * 2.2], i * 5));
s.links.forEach(([a, b], k) => {
  s.edgeData.set(s.nodeData.subarray(a * 5, a * 5 + 5), k * 10);
  s.edgeData.set(s.nodeData.subarray(b * 5, b * 5 + 5), k * 10 + 5);
});
// Drag to turn the graph (after the pointer has moved); otherwise it turns slowly.
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
if (s.moved && ctx.mouseDown) {
  s.yaw += (ctx.mouse[0] - ctx.mousePrev[0]) * 5;
  s.pitch = Math.max(-1.4, Math.min(1.4, s.pitch + (ctx.mouse[1] - ctx.mousePrev[1]) * 4));
} else s.yaw += ctx.dt * 0.15 * u.u_spin;
const [w, h] = ctx.resolution, dist = 3.2;
const eye = [dist * Math.cos(s.pitch) * Math.sin(s.yaw), dist * Math.sin(s.pitch), dist * Math.cos(s.pitch) * Math.cos(s.yaw)];
const mvp = M.multiply(M.perspective(40, w / h, 0.05, 20), M.lookAt(eye, [0, 0, 0], [0, 1, 0]));
gl.clearColor(0.02, 0.022, 0.035, 1); gl.clear(gl.COLOR_BUFFER_BIT);
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
gl.useProgram(s.program);
ctx.utils.setUniforms(s.program, { u_mvp: mvp, u_px: h / 260, u_edge: u.u_edges, u_palette: [[1, 0.42, 0.3], [0.3, 0.7, 1], [1, 0.8, 0.25], [0.45, 0.95, 0.55], [0.85, 0.45, 1], [0.3, 0.95, 0.9]].flat() });
for (const [part, data, mode, prim] of [[s.edges, s.edgeData, 0, gl.LINES], [s.nodes, s.nodeData, 1, gl.POINTS]]) {
  ctx.utils.setUniforms(s.program, { u_mode: mode });
  gl.bindVertexArray(part.vao); gl.bindBuffer(gl.ARRAY_BUFFER, part.b);
  gl.bufferData(gl.ARRAY_BUFFER, data, gl.DYNAMIC_DRAW);
  gl.drawArrays(prim, 0, data.length / 5);
}
gl.bindVertexArray(null); gl.disable(gl.BLEND);
ctx.publish("nodes", s.ids.length);
ctx.publish("links", s.links.length);
ctx.publish("steps", s.steps);
